import React from 'react';
import { Box, Button, Stack, Typography } from '@mui/material';
import { Api as ApiIcon, ArrowBack as BackIcon } from '@mui/icons-material';
import { Link as RouterLink } from 'react-router-dom';
import PartnerApiDocumentationContent from './PartnerApiDocumentationContent';
import { TopicIconBadge } from '../shared/TopicIconBadge';
import MarketingHeading from '../shared/MarketingHeading';

const PartnerApiDocumentationPage: React.FC = () => {
  return (
    <Box sx={{ maxWidth: 960, mx: 'auto', py: { xs: 2, md: 3 } }}>
      <Stack spacing={3}>
        <Box>
          <Button
            component={RouterLink}
            to="/partners"
            variant="text"
            size="small"
            startIcon={<BackIcon />}
            sx={{ mb: 1.5, ml: -0.5 }}
          >
            Back to partners
          </Button>
          <Stack direction="row" spacing={1.5} alignItems="center" sx={{ mb: 1.5 }}>
            <TopicIconBadge size="large">
              <ApiIcon />
            </TopicIconBadge>
            <Box>
              <MarketingHeading level="h1">
                Public API documentation
              </MarketingHeading>
              <Typography variant="subtitle1" color="primary.main" sx={{ fontWeight: 700 }}>
                Sustainow Carbon Intelligence · Partner integrations
              </Typography>
            </Box>
          </Stack>
          <Typography variant="body1" color="text.secondary" sx={{ maxWidth: 720 }}>
            REST endpoints for banks, auditors, verification agencies, and integration partners.
            MSME-facing JWT APIs remain unchanged; machine-to-machine access uses scoped partner API keys.
          </Typography>
        </Box>

        <PartnerApiDocumentationContent />
      </Stack>
    </Box>
  );
};

export default PartnerApiDocumentationPage;
