import React from 'react';
import { Box, type SxProps, type Theme } from '@mui/material';
import { alpha, useTheme } from '@mui/material/styles';

export interface TopicIconBadgeProps {
  children: React.ReactNode;
  size?: 'small' | 'medium' | 'large';
  color?: 'primary' | 'secondary' | 'warning' | 'info';
  sx?: SxProps<Theme>;
}

const SIZE_MAP = {
  small: 32,
  medium: 40,
  large: 48,
} as const;

/**
 * Rounded icon container used for section headings and highlight cards.
 */
export const TopicIconBadge: React.FC<TopicIconBadgeProps> = ({
  children,
  size = 'medium',
  color = 'primary',
  sx,
}) => {
  const theme = useTheme();
  const dimension = SIZE_MAP[size];
  const paletteColor = theme.palette[color].main;

  return (
    <Box
      aria-hidden
      sx={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        width: dimension,
        height: dimension,
        borderRadius: 2,
        flexShrink: 0,
        bgcolor: alpha(paletteColor, 0.12),
        color: `${color}.main`,
        ...sx,
      }}
    >
      {children}
    </Box>
  );
};

export default TopicIconBadge;
